from pathlib import Path
import json,re,collections
repository=Path(__file__).resolve().parents[1]
root=repository/('src/hub/reading-library' if (repository/'src/hub').is_dir() else 'reading-library')
reader=(root/'reader.js').read_text()
ui={
'pt':dict(title='Livros EduCashPro',lead='Três livros originais. Cada livro tem 12 capítulos e 20 parágrafos por capítulo. Leia no seu ritmo.',open='Ler livro',chapters='capítulos',back='Voltar à plataforma',offline='Baixar esta biblioteca para ler offline',notice='O download inclui os três materiais neste idioma. Tema e progresso são salvos neste navegador. O armazenamento pode ser removido nas configurações do aparelho.',saved='Arquivo preparado. Após salvar, você pode abri-lo sem conexão em um navegador compatível.',error='Não foi possível preparar o arquivo.',source='Sobre esta leitura'),
'en':dict(title='EduCashPro Books',lead='Three original books. Each has 12 chapters and 20 paragraphs per chapter. Read at your own pace.',open='Read book',chapters='chapters',back='Back to the platform',offline='Download this library for offline reading',notice='The download includes all three readings in this language. Theme and progress are saved in this browser. Device settings may remove stored data.',saved='File prepared. Once saved, it can be opened offline in a compatible browser.',error='Unable to prepare the file.',source='About this reading'),
'es':dict(title='Libros EduCashPro',lead='Tres libros originales. Cada libro tiene 12 capítulos y 20 párrafos por capítulo. Lee a tu ritmo.',open='Leer libro',chapters='capítulos',back='Volver a la plataforma',offline='Descargar esta biblioteca para leer sin conexión',notice='La descarga incluye las tres lecturas en este idioma. El tema y el progreso se guardan en este navegador. Los ajustes del dispositivo pueden borrar los datos.',saved='Archivo preparado. Después de guardarlo, puedes abrirlo sin conexión en un navegador compatible.',error='No se pudo preparar el archivo.',source='Sobre esta lectura'),
'ru':dict(title='Книги EduCashPro',lead='Три оригинальные книги. В каждой 12 глав и по 20 абзацев в главе. Читайте в удобном темпе.',open='Читать книгу',chapters='глав',back='Вернуться на платформу',offline='Скачать библиотеку для чтения офлайн',notice='Скачивание включает три материала на этом языке. Тема и прогресс сохраняются в браузере. Настройки устройства могут удалить сохранённые данные.',saved='Файл подготовлен. После сохранения его можно открыть без сети в совместимом браузере.',error='Не удалось подготовить файл.',source='Об этом материале')}
bootstrap=r'''(function(){const books=JSON.parse(document.getElementById('readingData').textContent),ui=JSON.parse(document.getElementById('readingUi').textContent),language=document.documentElement.lang.slice(0,2),target=document.getElementById('readingMount');
function download(){try{const copy=document.documentElement.cloneNode(true);copy.querySelector('#readingMount').innerHTML='';copy.querySelector('#offlineState').textContent='';const blob=new Blob(['<!doctype html>\n'+copy.outerHTML],{type:'text/html;charset=utf-8'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='EduCashPro-leituras-'+language+'.html';link.click();setTimeout(()=>URL.revokeObjectURL(url),30000);document.getElementById('offlineState').textContent=ui.saved;}catch{document.getElementById('offlineState').textContent=ui.error;}}
function route(){const requested=new URLSearchParams(location.hash.slice(1)).get('book'),book=books.find(b=>b.id===requested);if(!book){home();return;}window.EduCashProReadingLibrary.open({book,target,back:()=>{location.hash='';home()},download});}
function home(){target.innerHTML='';for(const book of books){const article=document.createElement('article');article.className='libraryCard';const h=document.createElement('h2');h.textContent=book.title;const p=document.createElement('p');p.textContent=book.attribution;const small=document.createElement('p');small.textContent=book.chapters.length+' '+ui.chapters;const button=document.createElement('button');button.textContent=ui.open;button.onclick=()=>{location.hash='book='+book.id;route()};article.append(h,p,small,button);target.append(article)}}
document.getElementById('downloadLibrary').onclick=download;window.addEventListener('hashchange',route);route();
if(location.protocol==='https:'&&'serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
})();'''
css='''*{box-sizing:border-box}body{margin:0;background:#071321;color:#eaf2f9;font-family:system-ui,-apple-system,sans-serif}.libraryShell{max-width:1000px;margin:auto;padding:20px 16px 60px}.libraryTop{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:12px;padding:12px 0;border-bottom:1px solid #28394c}.libraryTop a{color:#8ee4ce;text-decoration:none}.libraryLanguages{display:flex;gap:8px}.libraryLanguages a{padding:8px;border:1px solid #30475a;border-radius:8px;font-size:13px}.libraryLanguages a[aria-current=page]{background:#174337}.libraryShell>h1{font-size:28px;margin:28px 0 10px}.libraryLead,.libraryNotice{color:#a9bfd2;line-height:1.7;font-size:14px}.libraryNotice{font-size:12px}.libraryCard{padding:20px;margin:16px 0;border:1px solid #283e52;background:#0d1e30;border-radius:14px}.libraryCard h2{font-size:20px;line-height:1.4}.libraryCard p{font-size:13px;line-height:1.7;color:#acc0d1}button{cursor:pointer;min-height:44px;padding:10px 15px;border-radius:9px;border:1px solid #427168;background:#143a33;color:#d3fff1;font:600 14px system-ui}button:focus-visible,a:focus-visible,select:focus-visible{outline:2px solid #39e6b4;outline-offset:3px}#readingMount{margin-top:24px}#offlineState{font-size:13px;line-height:1.6;color:#a9e5d3}'''
for l in ui:
 books=[]
 for ident in ['business-21-study','financial-education-study','build-a-business']:
  book=json.loads((root/(ident+'.'+l+'.json')).read_text())
  for ch in book['chapters']:
   assert len(ch['paragraphs'])==20
   assert all(len(p.strip())>=100 for p in ch['paragraphs']),(l,ident,ch['title'])
  books.append(book)
 c=ui[l]
 languages=''.join(f'<a href="./library.{code}.html" lang="{code}" '+('aria-current="page"' if l==code else '')+f'>{code.upper()}</a>' for code in ui)
 doc=f'''<!doctype html><html lang="{l}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#071321"><title>EduCashPro | {c['title']}</title><style>{css}</style></head><body><main class="libraryShell"><nav class="libraryTop"><a href="../?view=learn&lang={l}">← {c['back']}</a><nav class="libraryLanguages" aria-label="Language">{languages}</nav></nav><h1>{c['title']}</h1><p class="libraryLead">{c['lead']}</p><button id="downloadLibrary">{c['offline']}</button><p class="libraryNotice">{c['notice']}</p><p id="offlineState" role="status"></p><div id="readingMount"></div></main><script id="readingData" type="application/json">{json.dumps(books,ensure_ascii=False).replace('<','&lt;')}</script><script id="readingUi" type="application/json">{json.dumps(c,ensure_ascii=False)}</script><script>{reader}</script><script>{bootstrap}</script></body></html>'''
 (root/('library.'+l+'.html')).write_text(doc)
 print(l,len(doc.encode()),'bytes',sum(len(b['chapters'])for b in books),'chapters')
(root/'sw.js').write_text('''const CACHE='educashpro-readings-20261029-3';self.addEventListener('install',e=>{self.skipWaiting()});self.addEventListener('activate',e=>e.waitUntil((async()=>{for(const name of await caches.keys())if(name.startsWith('educashpro-readings-')&&name!==CACHE)await caches.delete(name);await self.clients.claim()})()));self.addEventListener('fetch',event=>{const u=new URL(event.request.url);if(event.request.method!=='GET'||u.origin!==location.origin||!u.pathname.includes('/reading-library/library.')||!u.pathname.endsWith('.html'))return;event.respondWith((async()=>{const cache=await caches.open(CACHE);try{const response=await fetch(event.request);if(response.ok)await cache.put(event.request,response.clone());return response}catch{return await cache.match(event.request)||new Response('Open a previously downloaded reading.',{status:503})}})())});''')
